-- migration_106_speaking_warmup_bank.sql (2026-11-05)
-- The daily speaking warm-up uses Mr Ikromov's "Part 1 · Always in use"
-- question bank: Work and studies · Hometown · Home · The area where you live
-- (18 questions with band 8 model answers, 54 phrases, grammar spotlights).
-- Stored as a speaking set marked "warmup", so the examiner's voice works
-- for these lines, but it is not a test and gets no Practice Bank pages.
-- Needs migration_101 (speaking sets) and 104 (warm-up).

create or replace function public.speaking_set_pages()
returns trigger
language plpgsql
security definer
set search_path = public
as $function$
declare
  v_p1 text;
  v_p2 text;
  v_p3 text;
begin
  if tg_op = 'DELETE' then
    delete from public.materials where storage_path like 'speaking:' || old.id || '#%';
    return old;
  end if;

  -- The daily warm-up bank (content.warmup) is not a test: no Practice Bank pages.
  if coalesce((new.content->>'warmup')::boolean, false) then
    delete from public.materials where storage_path like 'speaking:' || new.id || '#%';
    return new;
  end if;

  select string_agg(t->>'topic', ' · ') into v_p1 from jsonb_array_elements(coalesce(new.content->'part1', '[]'::jsonb)) t;
  v_p2 := coalesce(new.content#>>'{part2,cue}', 'Cue card');
  v_p3 := coalesce(nullif(new.content#>>'{part3,title}', ''), initcap(coalesce(nullif(new.content#>>'{part3,theme}', ''), 'Discussion')));

  insert into public.materials
    (title, file_name, storage_path, url, mime_type, size_bytes, source,
     skill, question_type, collection, position, on_shelf, created_by)
  values
    ('Set ' || new.number || ': ' || coalesce(nullif(new.topics, ''), new.title), new.title, 'speaking:' || new.id || '#full', 'speaking:' || new.id || '#full', 'application/json', 0, 'upload', 'speaking', 'speaking_full', 'Speaking Tests · Full tests', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || coalesce(v_p1, 'Part 1'), new.title, 'speaking:' || new.id || '#part1', 'speaking:' || new.id || '#part1', 'application/json', 0, 'upload', 'speaking', 'speaking_part1', 'Speaking Tests · Part 1', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p2, new.title, 'speaking:' || new.id || '#part2', 'speaking:' || new.id || '#part2', 'application/json', 0, 'upload', 'speaking', 'speaking_part2', 'Speaking Tests · Part 2', new.number, false, new.created_by),
    ('Set ' || new.number || ': ' || v_p3, new.title, 'speaking:' || new.id || '#part3', 'speaking:' || new.id || '#part3', 'application/json', 0, 'upload', 'speaking', 'speaking_part3', 'Speaking Tests · Part 3', new.number, false, new.created_by)
  on conflict (storage_path) do update
    set title = excluded.title, file_name = excluded.file_name, position = excluded.position;
  return new;
end;
$function$;

insert into public.speaking_sets (id, number, title, topics, content, created_by)
values (
  '5e7a0001-0000-4000-8000-0000000000a1', 0, 'Warm-up bank', 'Work and studies · Hometown · Home · Your area',
  $wu${"warmup": true, "title": "Part 1 · Always in use", "part1": [{"topic": "Work and studies", "intro": "Now, in this first part, I’d like to ask you some questions about yourself. Let’s talk about your work and studies.", "questions": [{"q": "Do you work or are you a student?", "model": {"answer": "I’m a full-time student, majoring in business and economics, and I’m in my third year. I also do some tutoring on the side, which helps me make a bit of pocket money and gain hands-on experience.", "phrases": [["tutoring", "teaching students privately"], ["make pocket money", "earn small amounts of spending money"], ["hands-on experience", "practical experience gained by doing"]], "grammar": [{"pattern": "majoring in + subject", "use": "majoring in + subject: studying a subject as the main part of a degree", "example": "majoring in business and economics", "try": "I’m majoring in ______."}, {"pattern": "which helps me + base verb", "use": "clause + , which helps me + base verb: a benefit", "example": "which helps me make a bit of pocket money", "try": "…, which helps me ______."}]}}, {"q": "What do you like about your studies/work?", "model": {"answer": "What I enjoy most is that every lecture is intellectually stimulating. I love seeing how theories apply to the real world, and I’ve made friends who share my passion for the subject, which keeps me motivated.", "phrases": [["intellectually stimulating", "making you think in an interesting way"], ["apply to the real world", "be useful in actual situations"], ["share a passion for", "both love the same thing"]], "grammar": [{"pattern": "What I + verb + is that", "use": "what I enjoy most is that + clause: a cleft sentence", "example": "What I enjoy most is that every lecture is intellectually stimulating", "try": "What I like most is that ______."}, {"pattern": "I’ve made friends who", "use": "I’ve + past participle + noun + who: a present result", "example": "I’ve made friends who share my passion for the subject", "try": "I’ve made friends who ______."}]}}, {"q": "Is there anything you dislike about it?", "model": {"answer": "Honestly, the workload can be overwhelming, particularly around exams, when I have to juggle several assignments at once. I also find early morning classes a real struggle, since I’m not much of a morning person.", "phrases": [["overwhelming", "too much to cope with"], ["juggle", "manage several tasks at the same time"], ["a morning person", "someone who feels best early in the day"]], "grammar": [{"pattern": "particularly + time clause", "use": "particularly around + noun, when + clause: a specific moment", "example": "particularly around exams, when I have to juggle several assignments at once", "try": "…, particularly around ______, when ______."}, {"pattern": "I find + object + adjective / noun", "use": "I find + noun + a real + noun: a personal view", "example": "I also find early morning classes a real struggle", "try": "I find ______ a real ______."}]}}, {"q": "Would you like to change your major/job in the future?", "model": {"answer": "Not at the moment, although I might branch out into data analysis later on. Business is such a versatile field that I could switch careers without starting from scratch, so I’m keeping my options open.", "phrases": [["branch out", "expand into a new area"], ["switch careers", "change to a different job path"], ["keep your options open", "avoid deciding too early"]], "grammar": [{"pattern": "although + clause", "use": "although + clause: a contrast", "example": "although I might branch out into data analysis later on", "try": "Not at the moment, although ______."}, {"pattern": "such a + adjective + noun that", "use": "such a + adjective + noun + that + result", "example": "Business is such a versatile field that I could switch careers", "try": "It’s such a ______ that ______."}]}}]}, {"topic": "Hometown", "intro": "Now let’s talk about your hometown.", "questions": [{"q": "Where is your hometown?", "model": {"answer": "I come from a mid-sized city in the east of the country, about three hours from the capital by train. It’s nestled between two mountain ranges, so the scenery is stunning, and I’ve always felt a strong sense of belonging there.", "phrases": [["nestled", "located in a sheltered, pleasant position"], ["stunning", "extremely beautiful"], ["a sense of belonging", "the feeling of being part of a place"]], "grammar": [{"pattern": "come from + place", "use": "I come from + place: where you were born or raised", "example": "I come from a mid-sized city in the east of the country", "try": "I come from ______."}, {"pattern": "It’s + past participle + between", "use": "It’s nestled / located + between + noun: a position", "example": "It’s nestled between two mountain ranges", "try": "It’s ______ between ______."}]}}, {"q": "What’s your hometown well-known for?", "model": {"answer": "It’s famous for its historic old town and its lively bazaar, where you can find everything from fresh fruit to handmade crafts. Visitors also flock there for the food, as the local dishes are mouth-watering.", "phrases": [["a historic old town", "an old part of a city with history"], ["a bazaar", "a traditional market"], ["flock to", "go somewhere in large numbers"]], "grammar": [{"pattern": "be famous for + noun", "use": "be famous for + noun: well known because of", "example": "It’s famous for its historic old town", "try": "It’s famous for ______."}, {"pattern": "everything from … to …", "use": "everything from + noun + to + noun: a wide range", "example": "everything from fresh fruit to handmade crafts", "try": "You can find everything from ______ to ______."}]}}, {"q": "Is it a good place to raise kids?", "model": {"answer": "I’d say so. It’s safe and close-knit, and there are plenty of parks, so children can play outdoors freely. On top of that, the schools are reputable, and the cost of living is lower than in the capital, which makes it family-friendly.", "phrases": [["close-knit", "with strong relationships between people"], ["reputable", "having a good reputation"], ["the cost of living", "how much you need to spend to live"]], "grammar": [{"pattern": "plenty of + noun", "use": "there are plenty of + plural noun: a large number", "example": "there are plenty of parks", "try": "There are plenty of ______."}, {"pattern": "lower than in + place", "use": "comparative + than in + place: a comparison", "example": "the cost of living is lower than in the capital", "try": "It’s ______ than in ______."}]}}, {"q": "Is there anything you dislike about your hometown?", "model": {"answer": "If I had to pick one thing, it would be the lack of entertainment options for young people. There aren’t many cinemas or trendy cafés, so people often have to travel to the capital for a night out. It can be a bit of a drawback.", "phrases": [["entertainment options", "places or activities for leisure"], ["trendy", "fashionable"], ["a drawback", "a disadvantage"]], "grammar": [{"pattern": "If I had to + base verb, it would be", "use": "If I had to pick one thing, it would be + noun: a second conditional", "example": "If I had to pick one thing, it would be the lack of entertainment options", "try": "If I had to choose, it would be ______."}, {"pattern": "the lack of + noun", "use": "the lack of + noun: not having enough", "example": "the lack of entertainment options for young people", "try": "the lack of ______."}]}}]}, {"topic": "House and apartment", "intro": "Let’s talk about your home.", "questions": [{"q": "Do you live in a house or an apartment?", "model": {"answer": "I live in an apartment on the fourth floor of a high-rise block. It’s cosy and well-located, with a supermarket and a metro station just around the corner, although the stairs can be a bit of a pain when the lift is broken.", "phrases": [["a high-rise", "a very tall building"], ["cosy", "warm, comfortable and small"], ["well-located", "in a convenient position"]], "grammar": [{"pattern": "with + noun", "use": "with + noun: describing what a place has", "example": "with a supermarket and a metro station just around the corner", "try": "It’s ______, with ______."}, {"pattern": "when + present simple", "use": "when + present simple: a repeated situation", "example": "when the lift is broken", "try": "…, when the ______ is ______."}]}}, {"q": "What can you see from the windows of your home?", "model": {"answer": "From the living room, I can see a courtyard full of mature trees, and in the distance there’s a glimpse of the mountains. It’s not exactly breathtaking, but it’s a soothing sight, particularly at sunset.", "phrases": [["a courtyard", "an open space surrounded by buildings"], ["breathtaking", "extremely beautiful"], ["soothing", "calming"]], "grammar": [{"pattern": "full of + noun", "use": "full of + plural noun: containing many", "example": "a courtyard full of mature trees", "try": "a ______ full of ______."}, {"pattern": "in the distance", "use": "in the distance + there’s: far away", "example": "in the distance there’s a glimpse of the mountains", "try": "In the distance, there’s ______."}]}}, {"q": "What color would you choose to paint your room?", "model": {"answer": "I’d go for a soft shade of sage green. It creates a calming atmosphere and works well with natural light. I find bright colours rather overwhelming, whereas green helps me unwind after a long day.", "phrases": [["sage green", "a soft, greyish green"], ["a calming atmosphere", "a relaxing feeling in a place"], ["unwind", "relax after stress"]], "grammar": [{"pattern": "I’d go for + noun", "use": "I’d go for + noun: a polite choice", "example": "I’d go for a soft shade of sage green", "try": "I’d go for ______."}, {"pattern": "works well with", "use": "work well with + noun: suit or match", "example": "works well with natural light", "try": "It works well with ______."}]}}, {"q": "Is there any color you would never use for your room?", "model": {"answer": "Definitely red. It’s far too intense, and I’d find it hard to relax surrounded by it. I’d also steer clear of black, as it can make a room feel gloomy and claustrophobic.", "phrases": [["intense", "very strong"], ["steer clear of", "avoid"], ["claustrophobic", "uncomfortably small and enclosed"]], "grammar": [{"pattern": "far too + adjective", "use": "far too + adjective: much too", "example": "It’s far too intense", "try": "It’s far too ______."}, {"pattern": "make + object + base verb", "use": "make + object + base verb: cause", "example": "it can make a room feel gloomy", "try": "It can make a room feel ______."}]}}, {"q": "Which room does your family spend most of the time in?", "model": {"answer": "Without question, the kitchen. It’s the heart of our home, where we catch up over dinner and swap stories about our day. My mum is a fantastic cook, so there’s always something delicious on the stove.", "phrases": [["the heart of the home", "the most important place in a home"], ["catch up", "talk about what has happened recently"], ["swap stories", "tell each other about experiences"]], "grammar": [{"pattern": "where + clause", "use": "noun + , where + clause: describing a place", "example": "the kitchen. It’s the heart of our home, where we catch up over dinner", "try": "…, where we ______."}, {"pattern": "there’s always something + adjective", "use": "there’s always + noun: a regular feature", "example": "there’s always something delicious on the stove", "try": "There’s always something ______."}]}}]}, {"topic": "The area where you live", "intro": "Now let’s talk about the area where you live.", "questions": [{"q": "Can you describe the area where you live?", "model": {"answer": "It’s a leafy residential district on the outskirts of the city. It’s fairly quiet, but you’ll find everything you need within walking distance, such as a local market, a small library and a few cafés.", "phrases": [["leafy", "with many trees"], ["within walking distance", "close enough to walk to"], ["a local market", "a market in the neighbourhood"]], "grammar": [{"pattern": "everything you need", "use": "everything + (that) you need: a contact relative clause", "example": "you’ll find everything you need within walking distance", "try": "You’ll find everything you need ______."}, {"pattern": "such as", "use": "such as + noun: giving examples", "example": "such as a local market, a small library and a few cafés", "try": "…, such as ______."}]}}, {"q": "How long have you lived there?", "model": {"answer": "For about eight years now. We moved in when I was in secondary school, and I’ve grown attached to the place since then. I know most of my neighbours, and the sense of community is second to none.", "phrases": [["move in", "start living in a new home"], ["grow attached to", "gradually start to love something"], ["a sense of community", "feeling of belonging to a group"]], "grammar": [{"pattern": "for + period (present perfect)", "use": "I’ve lived + for + period: duration up to now", "example": "For about eight years now", "try": "I’ve lived here for ______."}, {"pattern": "when I was + place", "use": "when + past simple: a point in the past", "example": "We moved in when I was in secondary school", "try": "We moved in when I was ______."}]}}, {"q": "Do you think you’ll continue living there in the future?", "model": {"answer": "Probably not forever. Once I graduate, I’ll most likely relocate to wherever I can find a good job. That said, it will always be a home away from home, and I’d love to move back one day to settle down.", "phrases": [["relocate", "move to a different place"], ["a home away from home", "a place where you feel completely comfortable"], ["settle down", "start a stable life in one place"]], "grammar": [{"pattern": "Once + present simple", "use": "once + present simple, will + base verb: a future condition", "example": "Once I graduate, I’ll most likely relocate", "try": "Once I ______, I’ll ______."}, {"pattern": "wherever + clause", "use": "wherever + subject + verb: in any place", "example": "wherever I can find a good job", "try": "I’ll go wherever ______."}]}}, {"q": "What do you like most about your area?", "model": {"answer": "What I like most is how peaceful it is, even though it’s only fifteen minutes from the centre. It’s a real oasis of calm, and it’s ideal for an evening stroll with fresh air and plenty of green space.", "phrases": [["peaceful", "quiet and calm"], ["an oasis of calm", "a calm place in a busy area"], ["green space", "parks and areas with plants"]], "grammar": [{"pattern": "how + adjective + it is", "use": "what I like most is how + adjective + it is: a noun clause", "example": "What I like most is how peaceful it is", "try": "What I like most is how ______ it is."}, {"pattern": "even though", "use": "even though + clause: a surprising contrast", "example": "even though it’s only fifteen minutes from the centre", "try": "…, even though ______."}]}}, {"q": "Is there anything you’d love to change about it?", "model": {"answer": "If I could, I’d improve the public transport. Buses are few and far between, so you often end up waiting ages. I’d also like to see more cycle lanes, as that would cut down on traffic and make the air cleaner.", "phrases": [["few and far between", "rare, with long gaps between them"], ["cycle lane", "a road lane for bicycles"], ["cut down on", "reduce"]], "grammar": [{"pattern": "If I could, I’d + base verb", "use": "If I could, I’d + base verb: a hypothetical wish", "example": "If I could, I’d improve the public transport", "try": "If I could, I’d ______."}, {"pattern": "end up + -ing", "use": "end up + -ing: a final result", "example": "you often end up waiting ages", "try": "You often end up ______ing."}]}}]}]}$wu$::jsonb, null)
on conflict (id) do update
  set title = excluded.title, topics = excluded.topics, content = excluded.content, updated_at = now();

-- Check: 4 topics, 18 questions, no pages.
select (select jsonb_array_length(content->'part1') from public.speaking_sets where id = '5e7a0001-0000-4000-8000-0000000000a1') as topics,
       (select count(*) from public.speaking_sets s, jsonb_array_elements(s.content->'part1') t, jsonb_array_elements(t->'questions') q where s.id = '5e7a0001-0000-4000-8000-0000000000a1') as questions,
       (select count(*) from public.materials where storage_path like 'speaking:5e7a0001-0000-4000-8000-0000000000a1#%') as pages;
